/**
 * zod schema definition for the entity MJ_BizApps_FPNA: Assumption Sets
 */
export const mjBizAppsFPNAAssumptionSetSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    PlanID: z.string().describe(`
        * * Field Name: PlanID
        * * Display Name: Plan ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Plans (vwPlans.ID)`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(200)
        * * Description: Human label for this version of the assumptions.`),
    EffectiveFrom: z.date().describe(`
        * * Field Name: EffectiveFrom
        * * Display Name: Effective From
        * * SQL Data Type: datetimeoffset
        * * Description: First instant this set applies from. UTC.`),
    Status: z.union([z.literal('Active'), z.literal('Draft'), z.literal('Retired')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Draft
    *   * Retired
        * * Description: Draft, Active or Retired. Only an Active set should back a published run.`),
    PipelineCashMinWeight: z.number().describe(`
        * * Field Name: PipelineCashMinWeight
        * * Display Name: Pipeline Cash Min Weight
        * * SQL Data Type: decimal(5, 4)
        * * Default Value: 0.90
        * * Description: Minimum line Weight for a pipeline deal to contribute cash. Deals below it contribute zero rather than a fraction, because payroll cannot be met with fractional promises.`),
    NearTermDecayDays: z.number().describe(`
        * * Field Name: NearTermDecayDays
        * * Display Name: Near Term Decay Days
        * * SQL Data Type: int
        * * Default Value: 45
        * * Description: Length of the near-term ramp over which unbacked new-business budget decays to zero. A ramp, not a step, so there is no cliff at the boundary.`),
    CollectionLagDaysDefault: z.number().describe(`
        * * Field Name: CollectionLagDaysDefault
        * * Display Name: Collection Lag Days Default
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Default days from due date to observed cash, used where no per-customer override exists.`),
    RenewalChurnRate: z.number().describe(`
        * * Field Name: RenewalChurnRate
        * * Display Name: Renewal Churn Rate
        * * SQL Data Type: decimal(9, 6)
        * * Default Value: 0
        * * Description: Reserve rate applied to Assumed-confidence renewal lines. Applied as a visible reserve line, never as a haircut baked into the renewal itself.`),
    WeekEndingDay: z.number().describe(`
        * * Field Name: WeekEndingDay
        * * Display Name: Week Ending Day
        * * SQL Data Type: tinyint
        * * Default Value: 5
        * * Description: Week convention, 0=Sunday..6=Saturday, default 5 (Friday). A view concern; changing it never rewrites stored lines.`),
    DistributionLookaheadDaysDefault: z.number().describe(`
        * * Field Name: DistributionLookaheadDaysDefault
        * * Display Name: Distribution Lookahead Days Default
        * * SQL Data Type: int
        * * Default Value: 90
        * * Description: Default forward window the distribution policy evaluates its trough over, where a company has no per-entity override.`),
    Notes: z.string().nullable().describe(`
        * * Field Name: Notes
        * * Display Name: Notes
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Why these values, and who set them.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    DefaultProbability: z.number().describe(`
        * * Field Name: DefaultProbability
        * * Display Name: Default Probability
        * * SQL Data Type: decimal(5, 4)
        * * Default Value: 0.50
        * * Description: Deal Probability used when the sales row has none. 0–1. Not inferred from other deals.`),
    CommitCashMinWeight: z.number().describe(`
        * * Field Name: CommitCashMinWeight
        * * Display Name: Commit Cash Min Weight
        * * SQL Data Type: decimal(5, 4)
        * * Default Value: 0.90
        * * Description: Minimum Weight for an IncludeInCommit deal. The category floor, not a full-amount override. 0–1.`),
    Plan: z.string().describe(`
        * * Field Name: Plan
        * * Display Name: Plan
        * * SQL Data Type: nvarchar(200)`),
});

export type mjBizAppsFPNAAssumptionSetEntityType = z.infer<typeof mjBizAppsFPNAAssumptionSetSchema>;

