/**
 * zod schema definition for the entity MJ_BizApps_FPNA: Distribution Policies
 */
export const mjBizAppsFPNADistributionPolicySchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    CompanyID: z.string().describe(`
        * * Field Name: CompanyID
        * * Display Name: Company ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Companies (vwCompanies.ID)`),
    FloorType: z.union([z.literal('FixedAmount'), z.literal('MonthsOfOpex')]).describe(`
        * * Field Name: FloorType
        * * Display Name: Floor Type
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * FixedAmount
    *   * MonthsOfOpex
        * * Description: FixedAmount or MonthsOfOpex — how the cash floor is expressed.`),
    FloorAmount: z.number().nullable().describe(`
        * * Field Name: FloorAmount
        * * Display Name: Floor Amount
        * * SQL Data Type: decimal(19, 4)
        * * Description: Floor in currency, when FloorType is FixedAmount.`),
    FloorMonths: z.number().nullable().describe(`
        * * Field Name: FloorMonths
        * * Display Name: Floor Months
        * * SQL Data Type: decimal(9, 4)
        * * Description: Floor as N months of trailing operating expense, when FloorType is MonthsOfOpex.`),
    LookaheadDays: z.number().describe(`
        * * Field Name: LookaheadDays
        * * Display Name: Lookahead Days
        * * SQL Data Type: int
        * * Description: Forward window whose minimum projected cash is tested against the floor. 90 or 180, per entity.`),
    DistributionYearStartMonth: z.number().describe(`
        * * Field Name: DistributionYearStartMonth
        * * Display Name: Year Start Month
        * * SQL Data Type: tinyint
        * * Default Value: 1
        * * Description: Month the distribution year begins. Ours is February.`),
    DistributionYearStartDay: z.number().describe(`
        * * Field Name: DistributionYearStartDay
        * * Display Name: Year Start Day
        * * SQL Data Type: tinyint
        * * Default Value: 1
        * * Description: Day of that month the distribution year begins. Ours is the 15th, so the year runs 2/15 to 1/15. Month alone cannot express it, and a calendar-year assumption resets the preference tier two weeks early for every entity.`),
    EffectiveFrom: z.date().describe(`
        * * Field Name: EffectiveFrom
        * * Display Name: Effective From
        * * SQL Data Type: datetimeoffset
        * * Description: First instant this version of the policy applies from.`),
    Status: z.union([z.literal('Active'), z.literal('Draft'), z.literal('Retired')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Active
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Draft
    *   * Retired
        * * Description: Draft, Active or Retired. Status is the authority — there is no parallel IsActive flag.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    MonthlyOpexBaseline: z.number().nullable().describe(`
        * * Field Name: MonthlyOpexBaseline
        * * Display Name: Monthly Opex Baseline
        * * SQL Data Type: decimal(19, 4)
        * * Description: Monthly operating-expense run-rate for FloorType=MonthsOfOpex. Floor = this × FloorMonths. Required when FloorType is MonthsOfOpex — not inferred from whatever Opex lines happen to be in the run.`),
    OpeningCashMaxAgeDays: z.number().describe(`
        * * Field Name: OpeningCashMaxAgeDays
        * * Display Name: Opening Cash Max Age (Days)
        * * SQL Data Type: int
        * * Default Value: 45
        * * Description: Maximum age in days of the CashBalance used as OpeningCash relative to AsOf. Older balances fail STALE_OPENING_CASH rather than silently driving the trough.`),
    Company: z.string().describe(`
        * * Field Name: Company
        * * Display Name: Company
        * * SQL Data Type: nvarchar(50)`),
});

export type mjBizAppsFPNADistributionPolicyEntityType = z.infer<typeof mjBizAppsFPNADistributionPolicySchema>;

