/**
 * zod schema definition for the entity MJ_BizApps_FPNA: Forecast Lines
 */
export const mjBizAppsFPNAForecastLineSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    RunID: z.string().describe(`
        * * Field Name: RunID
        * * Display Name: Run ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Forecast Runs (vwForecastRuns.ID)`),
    CompanyID: z.string().describe(`
        * * Field Name: CompanyID
        * * Display Name: Company ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Companies (vwCompanies.ID)`),
    StreamID: z.string().describe(`
        * * Field Name: StreamID
        * * Display Name: Stream ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Streams (vwStreams.ID)`),
    ForecastCategoryID: z.string().describe(`
        * * Field Name: ForecastCategoryID
        * * Display Name: Forecast Category ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Forecast Categories (vwForecastCategories.ID)`),
    StatementLineID: z.string().nullable().describe(`
        * * Field Name: StatementLineID
        * * Display Name: Statement Line ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Statement Lines (vwStatementLines.ID)`),
    GLAccountID: z.string().nullable().describe(`
        * * Field Name: GLAccountID
        * * Display Name: GL Account ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_Accounting: GL Accounts (vwGLAccounts.ID)`),
    LineKey: z.string().describe(`
        * * Field Name: LineKey
        * * Display Name: Line Key
        * * SQL Data Type: nvarchar(200)
        * * Description: Stable identity across runs and snapshots. The bridge matches on this, never on the row's UUID, which is regenerated every run.`),
    ExpectedAt: z.date().describe(`
        * * Field Name: ExpectedAt
        * * Display Name: Expected At
        * * SQL Data Type: datetimeoffset
        * * Description: When the cash moves. Stored to the day; week and month buckets are derived at read time in the company's operating time zone and never persisted.`),
    Amount: z.number().describe(`
        * * Field Name: Amount
        * * Display Name: Amount
        * * SQL Data Type: decimal(19, 4)
        * * Description: Cash contribution, signed. For a budget residual this is gross less what has been displaced.`),
    GrossAmount: z.number().describe(`
        * * Field Name: GrossAmount
        * * Display Name: Gross Amount
        * * SQL Data Type: decimal(19, 4)
        * * Description: Amount before displacement. Equals Amount for any line that is not a budget residual.`),
    DisplacedAmount: z.number().describe(`
        * * Field Name: DisplacedAmount
        * * Display Name: Displaced Amount
        * * SQL Data Type: decimal(19, 4)
        * * Default Value: 0
        * * Description: Magnitude displaced by higher-fidelity lines. Never exceeds the magnitude of GrossAmount, so a residual reaches zero and never inverts.`),
    CurrencyID: z.string().describe(`
        * * Field Name: CurrencyID
        * * Display Name: Currency ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_Accounting: Currencies (vwCurrencies.ID)
        * * Description: Currency this line is denominated in — the company's functional currency. FK to __mj_BizAppsAccounting.Currency, resolved from AccountingCompanyProfile.FunctionalCurrencyCode. Single-currency until multi-currency activates upstream (accounting D16 / orders MOD-4).`),
    Weight: z.number().describe(`
        * * Field Name: Weight
        * * Display Name: Weight
        * * SQL Data Type: decimal(5, 4)
        * * Default Value: 1
        * * Description: Source confidence, 0 to 1. A 35% pipeline deal keeps its 0.35 here; cash inclusion is a separate test against the assumption set's threshold.`),
    OriginEntityID: z.string().nullable().describe(`
        * * Field Name: OriginEntityID
        * * Display Name: Origin Entity ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Entities (vwEntities.ID)
        * * Description: Entity of the source record in __mj.Entity. NULL until the source app is wired.`),
    OriginRecordID: z.string().nullable().describe(`
        * * Field Name: OriginRecordID
        * * Display Name: Origin Record ID
        * * SQL Data Type: nvarchar(400)
        * * Description: Primary key of the source record, as text.`),
    OriginLabel: z.string().nullable().describe(`
        * * Field Name: OriginLabel
        * * Display Name: Origin Label
        * * SQL Data Type: nvarchar(200)
        * * Description: Human-readable source reference, e.g. 'Acme INV-1042'.`),
    ParentForecastLineID: z.string().nullable().describe(`
        * * Field Name: ParentForecastLineID
        * * Display Name: Parent Forecast Line ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Forecast Lines (vwForecastLines.ID)
        * * Description: The line this one derives from — a commission points at the receipt it is calculated on.`),
    AdjustmentID: z.string().nullable().describe(`
        * * Field Name: AdjustmentID
        * * Display Name: Adjustment ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Manual Adjustments (vwManualAdjustments.ID)
        * * Description: The manual override that produced this line, when it came from one rather than from a source system.`),
    ConfidenceClass: z.union([z.literal('Assumed'), z.literal('Contracted')]).nullable().describe(`
        * * Field Name: ConfidenceClass
        * * Display Name: Confidence Class
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Assumed
    *   * Contracted
        * * Description: Contracted (a signed term exists, amount used as-is) or Assumed (annualised, escalator applied). Provenance, deliberately distinct from likelihood: judgment is applied once as a visible reserve, never as a haircut on the line.`),
    IntercompanyPairKey: z.string().nullable().describe(`
        * * Field Name: IntercompanyPairKey
        * * Display Name: Intercompany Pair Key
        * * SQL Data Type: nvarchar(200)
        * * Description: Shared key linking the due-to line at one company to the due-from line at the other, so a pair can be asserted to net to zero on consolidation instead of inferred from sums.`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(200)
        * * Description: What the bridge shows for this line.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    Company: z.string().describe(`
        * * Field Name: Company
        * * Display Name: Company
        * * SQL Data Type: nvarchar(50)`),
    Stream: z.string().describe(`
        * * Field Name: Stream
        * * Display Name: Stream
        * * SQL Data Type: nvarchar(200)`),
    ForecastCategory: z.string().describe(`
        * * Field Name: ForecastCategory
        * * Display Name: Forecast Category
        * * SQL Data Type: nvarchar(200)`),
    StatementLine: z.string().nullable().describe(`
        * * Field Name: StatementLine
        * * Display Name: Statement Line
        * * SQL Data Type: nvarchar(200)`),
    GLAccount: z.string().nullable().describe(`
        * * Field Name: GLAccount
        * * Display Name: GL Account
        * * SQL Data Type: nvarchar(200)`),
    Currency: z.string().describe(`
        * * Field Name: Currency
        * * Display Name: Currency
        * * SQL Data Type: nvarchar(80)`),
    OriginEntity: z.string().nullable().describe(`
        * * Field Name: OriginEntity
        * * Display Name: Origin Entity
        * * SQL Data Type: nvarchar(255)`),
    ParentForecastLine: z.string().nullable().describe(`
        * * Field Name: ParentForecastLine
        * * Display Name: Parent Forecast Line
        * * SQL Data Type: nvarchar(200)`),
});

export type mjBizAppsFPNAForecastLineEntityType = z.infer<typeof mjBizAppsFPNAForecastLineSchema>;

