/**
 * zod schema definition for the entity MJ_BizApps_FPNA: Snapshot States
 */
export const mjBizAppsFPNASnapshotStateSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    SnapshotID: z.string().describe(`
        * * Field Name: SnapshotID
        * * Display Name: Snapshot ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Snapshots (vwSnapshots.ID)`),
    DistributionYear: z.number().describe(`
        * * Field Name: DistributionYear
        * * Display Name: Distribution Year
        * * SQL Data Type: int
        * * Description: The distribution year this state belongs to, identified by the year its start date falls in.`),
    YTDDistributed: z.number().describe(`
        * * Field Name: YTDDistributed
        * * Display Name: YTD Distributed
        * * SQL Data Type: decimal(19, 4)
        * * Description: Cumulative distributed within that year as of this photo. What decides whether a preference band is still open.`),
    CurrencyID: z.string().describe(`
        * * Field Name: CurrencyID
        * * Display Name: Currency ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_Accounting: Currencies (vwCurrencies.ID)
        * * Description: Currency of YTDDistributed.`),
    DistributionPolicyID: z.string().nullable().describe(`
        * * Field Name: DistributionPolicyID
        * * Display Name: Distribution Policy ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Distribution Policies (vwDistributionPolicies.ID)
        * * Description: The exact policy version this state was computed under.`),
    WaterfallSpecID: z.string().nullable().describe(`
        * * Field Name: WaterfallSpecID
        * * Display Name: Waterfall Spec ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ_BizApps_FPNA: Waterfall Specs (vwWaterfallSpecs.ID)
        * * Description: The exact waterfall version this state was computed under.`),
    IsSeed: z.boolean().describe(`
        * * Field Name: IsSeed
        * * Display Name: Is Seed
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: True for the opening balance of a distribution year that began before go-live. Without a seed the first run reads cumulative as zero and over-allocates the preference tier before it should flip.`),
    SeedSource: z.string().nullable().describe(`
        * * Field Name: SeedSource
        * * Display Name: Seed Source
        * * SQL Data Type: nvarchar(200)
        * * Description: Where the opening figure came from, e.g. the month-end partner distributions tracker. Required on a seed: this number decides who gets paid.`),
    SeedAsOf: z.date().nullable().describe(`
        * * Field Name: SeedAsOf
        * * Display Name: Seed As Of
        * * SQL Data Type: datetimeoffset
        * * Description: The date the seed figure was true as of.`),
    SeedEnteredByUserID: z.string().nullable().describe(`
        * * Field Name: SeedEnteredByUserID
        * * Display Name: Seed Entered By User ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Users (vwUsers.ID)
        * * Description: Who entered the seed.`),
    SeedReconciledAt: z.date().nullable().describe(`
        * * Field Name: SeedReconciledAt
        * * Display Name: Seed Reconciled At
        * * SQL Data Type: datetimeoffset
        * * Description: When the seed was verified against the system's own recorded distribution history. After this point the computed history is authoritative and the seed is no longer relied on.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    Currency: z.string().describe(`
        * * Field Name: Currency
        * * Display Name: Currency
        * * SQL Data Type: nvarchar(80)`),
    SeedEnteredByUser: z.string().nullable().describe(`
        * * Field Name: SeedEnteredByUser
        * * Display Name: Seed Entered By User
        * * SQL Data Type: nvarchar(100)`),
});

